'use client';
import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useUser } from '@/context/UserContext';
import { supabaseClient } from '@/lib/supabaseClient';
import Link from 'next/link';
import Loader from '@/components/Loader';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loginLoading, setLoginLoading] = useState(false);
  const router = useRouter();
  const { fetchUserProfile } = useUser();

  const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginLoading(true);
    try {
      const { error: authError } = await supabaseClient.auth.signInWithPassword({ email, password });
      if (authError) { setError(authError.message); setLoginLoading(false); return; }
      
      const res = await fetch('http://localhost:5001/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
        credentials: 'include', 
      });

      if (res.ok) {
        await fetchUserProfile();
        router.push('/');
      }
    } catch (err) { setError('Connection error'); } finally { setLoginLoading(false); }
  };

  return (
    <div className="relative min-h-screen w-full flex items-center justify-center custom-img p-4 overflow-hidden">
      {/* Muted dark charcoal/red overlay */}
      <div className="absolute inset-0 bg-[#0f172a]/80 backdrop-blur-xl z-10" />
      
      <div className="relative z-20 w-full max-w-[400px] bg-white rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.3)] border border-white/10 overflow-hidden">
        <div className="bg-[#1e293b] p-8 text-center border-b border-gray-100">
          <h2 className="text-2xl font-black uppercase tracking-widest text-white">Member Login</h2>
          <div className="h-1 w-12 bg-red-600 mx-auto mt-2" />
        </div>

        <form className="p-8 space-y-5" onSubmit={handleLogin}>
          <div className="space-y-1">
            <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Email</label>
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} 
                   className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl text-gray-900 focus:ring-2 focus:ring-red-600 outline-none transition" required />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Password</label>
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} 
                   className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl text-gray-900 focus:ring-2 focus:ring-red-600 outline-none transition" required />
          </div>
          
          <button type="submit" className="w-full py-4 bg-red-700 text-white font-bold uppercase tracking-widest rounded-xl hover:bg-red-800 transition-all shadow-lg active:scale-95">
            {loginLoading ? <Loader /> : 'Sign In'}
          </button>
          
          {error && <p className="text-red-600 text-center text-xs font-bold bg-red-50 p-2 rounded">{error}</p>}
          
          <p className="text-center text-xs text-gray-500 pt-4">
            New to the club? <Link href="/signup" className="text-red-700 font-bold hover:underline">Create Account</Link>
          </p>
        </form>
      </div>
    </div>
  );
}